/** The tech logos, as the registry's definitions. */
export const TECH_ICON_STENCILS: StencilDefinition[] = TECH_LOGOS.map((logo) => ({
  id: logo.id,
  title: logo.title,
  subtitle: '',
  description: `${logo.title} logo`,
  category: logo.category,
  defaultWidth: 64,
  defaultHeight: 64,
  accentColor: logo.color,
  viewBox: logo.viewBox,
  // The brand colour is the logo's own identity, so it is what the artwork
  // falls back to; an explicit `color` — the node's own colour, set when a user
  // recolours a placed logo — overrides it. Falling back to the theme's ink
  // instead would draw every logo as a monochrome glyph.
  render: ({ color, isDark }) => {
    const fill = color ?? logo.color ?? (isDark ? '#f4f4f5' : '#18181b');
    return `<g><path d="${logo.path}" fill="${fill}" /></g>`;
  },
}));
